-- Caso confirmado por el propietario el 09/10/2026; Sólo contenido editorial.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado)
VALUES ('pago-anticipado-beca-porcentaje',$texto$Pago anticipado completo: conservar beca del 20% y agregar beneficio del 10%$texto$,'Cobranza',$texto$Preparar dos mensualidades, conservar la beca, revisar el acuerdo y validar un pago completo con tarjeta; comprobar descuentos, saldos, banco y comprobante familiar.$texto$,$texto$Alumno con inscripción vigente, tutor financiero activo con acceso familiar, ciclo que cubra los dos meses, mismo plantel/moneda MXN, concepto COLEGIATURA que permita beca/descuento, sin abonos ni recargos activos en los cargos seleccionados. Administrador identificado con permisos. Usar datos de ensayo y adaptar fechas a inscripción/plazo; no transferir dinero real ni duplicar el caso ya realizado.$texto$,$texto$Noviembre y diciembre2026: cada original1000, beca200, base800, beneficio adicional80 y pago720. Totales original2000, beca400, base1600, beneficio160, recibido1440. Caso confirmado ANT-20261009-000001 / PAG-20261009-000024; banco18290→19730. Folios y saldos cambian en otros ensayos.$texto$,1,DATE '2026-10-09','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN permiso p ON p.codigo=ANY(ARRAY['CONCEPTO_COBRO_ADMINISTRAR','BECA_ALUMNO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','CONVENIO_PAGO_ADMINISTRAR','PAGO_REGISTRAR','PAGO_LEER','PAGO_VALIDAR','CUENTA_FINANCIERA_LEER']) WHERE g.slug='pago-anticipado-beca-porcentaje';
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('pago-anticipado-beca-porcentaje',1,$texto$Identificar alumno, tutor y saldo previo$texto$,$texto$Administración$texto$,$texto$Inscripciones, Tutores y Cuentas financieras$texto$,$texto$1. Entra a Operación escolar → Control escolar → Inscripciones, busca al alumno y consulta su inscripción: institución, plantel y ciclo deben cubrir noviembre y diciembre de 2026; En el caso probado inicia el 01/10/2026 y el ciclo termina el 15/06/2027; sin fin de inscripción se usa el límite del ciclo. 2. En Tutores consulta al responsable financiero y comprueba el vínculo activo con el alumno y su acceso familiar. No cambies vínculos de una prueba ya realizada. 3. Entra a Administración → Finanzas → Cuentas financieras; busca la cuenta bancaria del plantel → Aplicar filtros. Anota Saldo actual como B, no Saldo inicial. Abre su detalle y compara Saldo actual disponible. 4. Conserva la referencia del alumno y cuenta. Usa otra ventana privada para el tutor; no realices una transferencia bancaria real para ensayar.$texto$,$texto$Cuenta bancaria con saldo B; en el caso confirmado B = $18,290.00.$texto$,$texto$Alumno, tutor y cuenta identificados; ninguna operación nueva.$texto$,$texto$Si consultas el caso ya realizado, no vuelvas a capturar. Git no transporta la base de datos; los folios del ensayo sólo existen en su BD.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('pago-anticipado-beca-porcentaje',2,$texto$Crear el concepto de colegiatura$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Conceptos de cobro y busca ANTICIPO-TEST-01. Si corresponde al caso existente, sólo consulta. 2. Para un ensayo nuevo pulsa Nuevo registro y selecciona institución. Captura código ANTICIPO-TEST-01, nombre Colegiatura prueba pago anticipado y categoría Colegiatura; si ya se usó ese código para otra prueba, emplea uno nuevo. 3. Activa Permite beca, Permite descuento y Concepto activo. Deja Permite recargo desactivado para aislar este ejercicio. 4. Pulsa Crear concepto y comprueba código, categoría y opciones en el listado.$texto$,$texto$ANTICIPO-TEST-01 permite beca y descuento.$texto$,$texto$Concepto apto para la propuesta anticipada.$texto$,$texto$El acuerdo sólo selecciona colegiaturas elegibles; inscripción y otros cobros usan sus procesos ordinarios.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('pago-anticipado-beca-porcentaje',3,$texto$Asignar la beca antes de emitir adeudos$texto$,$texto$Administración$texto$,$texto$Becas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Becas por alumno → Nuevo registro. Selecciona institución, plantel e inscripción del alumno. 2. Selecciona un Tipo de beca activo y el concepto ANTICIPO-TEST-01. El concepto debe permitir becas. 3. Captura Modalidad Porcentaje, Porcentaje 20, Inicio 01/11/2026, Fin 31/12/2026, Estado Activa y Motivo y autorización: Beca del 20% para probar el beneficio adicional por pago anticipado de noviembre y diciembre. 4. Pulsa Asignar beca. Confirma que exista una sola beca activa compatible para este concepto y periodo antes de generar los cargos.$texto$,$texto$Beca del 20%: $200.00 por mensualidad original de $1,000.00.$texto$,$texto$Beca preparada; no ingresa dinero.$texto$,$texto$Las becas se aplican al emitir cargos; asignarla después no cambia automáticamente los adeudos existentes. Adapta fechas a la inscripción y ciclo de un nuevo ensayo.$texto$,$texto$/admin/catalogos/becas-alumno$texto$),
('pago-anticipado-beca-porcentaje',4,$texto$Configurar dos mensualidades de $1,000$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Crear cuota. Selecciona institución, plantel, inscripción y ANTICIPO-TEST-01. 2. Captura Importe individual 1000.00, Moneda MXN, Cada mes, Primer mes noviembre de 2026, Último mes diciembre de 2026 y Día límite de pago de cada mes 20; 3. Selecciona Estado Activa y activa Incluir en generación automática de cargos. En Configuración adicional · vigencia de la cuota verifica desde 01/11/2026 hasta 31/12/2026, dentro de inscripción/ciclo. 4. Pulsa Crear cuota; revisa alumno, importe y fechas en el modal y confirma. Si pruebas Cancelar, no debe guardar; luego vuelve a confirmar sólo una vez.$texto$,$texto$Dos meses de $1,000.00 cada uno, vencimientos 20/11/2026 y 20/12/2026.$texto$,$texto$Cuota mensual guardada; banco permanece B.$texto$,$texto$La vigencia de la configuración no es el plazo del acuerdo anticipado. No uses Una sola vez para generar dos mensualidades.$texto$,$texto$/admin/cuotas-alumno/nuevo$texto$),
('pago-anticipado-beca-porcentaje',5,$texto$Generar únicamente noviembre y diciembre$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos → Generar automáticos$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos. Selecciona institución y filtros de contexto; captura Generar hasta 31/12/2026; 2. Pulsa Visualizar cuotas de alumnos por aplicar → Desmarcar todos. Marca sólo noviembre y diciembre del alumno y concepto del ejercicio. Revisa por fila original1000, beca200 y saldo800. 3. Pulsa Confirmar y generar adeudos seleccionados; revisa el modal y confirma. Pulsa Volver a adeudos de alumnos. 4. En el listado busca alumno/ANTICIPO-TEST-01 → Con saldo pendiente → Aplicar filtros. Abre Ver de cada mes; confirma saldo800, dos cargos y deuda total1600 antes del acuerdo.$texto$,$texto$Noviembre $800.00 + diciembre $800.00 = $1,600.00 exigibles.$texto$,$texto$Beca aplicada a cada cargo; todavía sin beneficio adicional ni ingreso.$texto$,$texto$Si no aparece beca200 por mes, detén el ensayo y revisa su vigencia antes de pagar. No generes otras cuotas por dejar toda la lista seleccionada.$texto$,$texto$/admin/cargos/generar$texto$),
('pago-anticipado-beca-porcentaje',6,$texto$Preparar el acuerdo conservando la beca$texto$,$texto$Administración$texto$,$texto$Convenios de pago → Acuerdos por pago anticipado$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado → Nueva propuesta. Selecciona institución y Tutor responsable. 2. En Buscar mensualidades de los hijos enfoca para consultar diez opciones o escribe tres caracteres. Agrega únicamente noviembre y diciembre del alumno/concepto. Cada mensualidad queda en una tarjeta; Quitar sólo retira de la selección, no cancela deudas. 3. En ¿Cómo se combina con la beca vigente? selecciona Conservar beca y agregar beneficio. Beneficio autorizado: Porcentaje adicional; Valor del beneficio: 10; Fecha límite para pagar completo: 20/10/2026 en el ensayo original; para otro ensayo elige un plazo vigente posterior o igual al día del pago. 4. Captura Motivo y condiciones autorizadas: Se autoriza un beneficio adicional del 10% por pagar completas las colegiaturas de noviembre y diciembre antes del 20/10/2026, conservando la beca del 20%. Ajusta el texto si cambias la fecha. Pulsa Visualizar acuerdo; la pantalla baja automáticamente al resumen.$texto$,$texto$Base1600, beneficio160, pago completo1440.$texto$,$texto$Vista previa sin modificar cargos, becas ni banco.$texto$,$texto$No seleccionar otras deudas. El porcentaje se calcula después de la beca: 10% de800 es80; no equivale a descontar30% de1000.$texto$,$texto$/admin/convenios-pago/anticipados/nuevo$texto$),
('pago-anticipado-beca-porcentaje',7,$texto$Revisar el detalle y confirmar la propuesta$texto$,$texto$Administración$texto$,$texto$Preparar acuerdo → Así quedaría el acuerdo$texto$,$texto$1. En la sección Así quedaría el acuerdo revisa cada fila: Original1000, Beca conservada200, Otros ajustes previos0, Base acordada800, Beneficio adicional80 y Pago requerido720. 2. Comprueba totales: Base seleccionada1600, Beneficio propuesto160 y Pago completo requerido1440MXN. Si cambias un campo, vuelve a Visualizar acuerdo antes de guardar. 3. Pulsa Guardar propuesta y revisa el modal. Puedes pulsar Cancelar para volver sin guardar; repite Guardar propuesta y confirma una sola vez. 4. En el detalle comprueba Propuesta vigente, tutor, plazo y condiciones. Si consultas Adeudos de alumnos ahora, siguen debiendo800 por mes; Cuentas financieras conserva B.$texto$,$texto$Original2000 menos beca400 deja1600; beneficio160 deja1440.$texto$,$texto$Propuesta guardada y saldos sin cambios.$texto$,$texto$Guardar propuesta no publica el descuento ni recibe dinero. No guardar otra propuesta para los mismos cargos reservados.$texto$,$texto$/admin/convenios-pago/anticipados$texto$),
('pago-anticipado-beca-porcentaje',8,$texto$Registrar el pago completo desde el acuerdo$texto$,$texto$Administración$texto$,$texto$Detalle del acuerdo → Registrar pago completo como pendiente$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Convenios de pago → Acuerdos por pago anticipado, busca la propuesta → Ver. Localiza Registrar pago completo como pendiente. 2. Selecciona Método Tarjeta, Fecha y hora del pago reales dentro del plazo del acuerdo, Cuenta donde se recibió el dinero bancaria compatible y Referencia o autorización ANTICIPO-TEST-1440. Tarjeta no exige archivo en este formulario; transferencia sí requiere comprobante. 3. Pulsa Registrar pago completo. Comprueba en el modal tutor, cuenta, método e importe1440 y confirma. No captures un monto parcial para obtener el beneficio. 4. Conserva el folio generado y abre Ver pago. Todavía En revisión, banco B y deudas800 por mes: la validación pendiente no aplica el descuento.$texto$,$texto$En el ensayo se generó PAG-20261009-000024; en un ensayo nuevo el folio cambia.$texto$,$texto$Pago completo pendiente ligado al acuerdo.$texto$,$texto$Usa este formulario del acuerdo, no un Nuevo registro ordinario desvinculado. No repitas el pago al consultar el ejemplo terminado.$texto$,$texto$/admin/convenios-pago/anticipados$texto$),
('pago-anticipado-beca-porcentaje',9,$texto$Validar y publicar un solo ingreso$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Ver → Gestión$texto$,$texto$1. Desde Ver pago del acuerdo, o Administración → Finanzas → Pagos recibidos, busca la referencia/folio y abre Ver. Revisa que esté ligado al acuerdo y que el importe sea1440. 2. En Gestión → Control administrativo del pago comprueba la cuenta destino precargada. Para este ensayo conserva el monto, sin activar recibido mayor. Comprueba la distribución solicitada720 para noviembre y720 para diciembre. 3. Pulsa Validar y publicar; revisa el modal y confirma una sola vez. Si ya figura Validado, no crees ni valides otro pago. 4. En Cuentas financieras verifica Saldo actual B+1440. En el caso confirmado pasó de18290 a19730 mediante un ingreso1440. Si tienes una anotación distinta, compara el saldo anterior/posterior del movimiento antes de registrar cualquier ajuste.$texto$,$texto$Banco $18,290.00 + ingreso $1,440.00 = $19,730.00.$texto$,$texto$Pago validado y beneficio aplicado en la misma operación.$texto$,$texto$El propietario inicialmente anotó18890; lectura y comprobación posterior confirmaron18290→19730. No compensar600 ni repetir pagos por esa confusión. Administración debe tener identidad y permisos, no acceso de recuperación.$texto$,$texto$/admin/catalogos/pagos$texto$),
('pago-anticipado-beca-porcentaje',10,$texto$Comprobar adeudos, beca, comprobante y portal familiar$texto$,$texto$Administración y tutor$texto$,$texto$Adeudos, Acuerdos, Becas y Portal familiar$texto$,$texto$1. Entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca alumno/concepto → estado Todos o Liquidado → Aplicar filtros → Ver noviembre → Resumen. Comprueba original1000, Descuentos y becas280, Total del adeudo con ajustes720, Abonos vigentes720 y Falta por pagar0. En Historial → Historial de ajustes consulta BECA200 y DESCUENTO80 por acuerdo. Repite con diciembre: mismos valores. 2. En Convenios de pago → Acuerdos por pago anticipado → Ver comprueba Beneficio aplicado, beneficio total160 y pago1440. En Becas por alumno consulta la beca20% aún activa: no se convirtió en30% ni fue eliminada. 3. En otra ventana privada entra a /familias, inicia sesión como el tutor → selecciona al alumno → Tus pagos. Recarga: estas dos mensualidades no están pendientes; el historial conserva el pago1440 y su comprobante PDF debe abrir en otra pestaña. Otras deudas permanecen fuera del ensayo. 4. Comprueba Cuentas financieras saldoB+1440 y Pagos recibidos estadoValidado. El propietario confirmó todos estos puntos el09/10/2026; Deja el pago validado al cerrar el caso; cancelar o devolver es un escenario separado aún no confirmado.$texto$,$texto$Dos saldos0; beca400 total más beneficio160; pagos720+720=1440; bancoB+1440.$texto$,$texto$Caso confirmado completo, comprobante visible y beca conservada.$texto$,$texto$No aplicar ajuste manual ni cancelar cargo para liquidarlo. No dar por probadas mensualidad gratis, sustitución de beca, monto fijo, cancelación o devolución por haber concluido este caso.$texto$,$texto$/admin/catalogos/cargos$texto$)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
